 public Map<String,Object> list(RequestContext c,String kind,Map<String,String>q){return tx.execute(s->{var a=auth.authorize(c);if(kind.equals("sales"))a.require("rtn:sales:create","rtn:sales:receive","rtn:sales:inspect","rtn:sales:settle");else a.require(permission(kind),kind.equals("refunds")?"rtn:refund:pay":kind.equals("claims")?"rtn:claim:resolve":"rtn:purchase:ship");var rows=db.queryForList("SELECT * FROM "+table(kind)+" WHERE country_id=? ORDER BY id DESC",a.requireCountry()).stream().map(DbRows::camel).peek(r->{if(kind.equals("sales"))r.put("warehouseId",r.get("returnWarehouseId"));}).filter(a::canRow).map(r->fields.mask(a,detail(a,kind,r),kind.equals("purchase")?"COST":"ORDER_TOTAL")).filter(r->q.getOrDefault("status","").isBlank()||q.get("status").equals(r.get("status"))).toList();return page(rows,q);});}
