 public Map<String,Object> settleSales(RequestContext c,long id,Map<String,Object>b,String key){return command(c,"rtn:sales:settle","/api/v1/rtn/sales/"+id+"/settle",b,key,"ORDER_TOTAL",a->{
  var r=locked(a,"sales",id,b,true);if(!"PENDING_SETTLE".equals(r.get("status"))||Boolean.TRUE.equals(r.get("settledFlag")))throw state("SYS_STATE_INVALID","验货完成且未处理账款时才能结算");
  LocalDate date=date(a,b,"bizDate");periods.assertOpen(a.requireCountry(),id(r,"bookId"),date);
  var lines=db.queryForList("SELECT * FROM rtn_sales_return_line WHERE country_id=? AND return_id=? ORDER BY order_line_id,id FOR UPDATE",a.requireCountry(),id).stream().map(DbRows::camel).toList();
  var allocations=new ArrayList<Map<String,Object>>();BigDecimal total=BigDecimal.ZERO;
  for(var l:lines){
   if(n(l,"receivedQty").compareTo(n(l,"inspectedQty"))!=0)throw Inputs.bad("尚有未验货数量");
   if(n(l,"reservedQty").signum()>0&&String.valueOf(r.get("shortReason")).isBlank()&&Inputs.text(b,"shortReason","").isBlank())throw Inputs.bad("最终少收结算需要差额原因");
   BigDecimal qty=n(l,"inspectedQty");if(qty.signum()==0)continue;
   BigDecimal amount;
   if(l.get("outboundLineId")==null)amount=money(qty.multiply(n(l,"unitPrice")));
   else{
    long outboundLine=id(l,"outboundLineId");var original=sales.lockDeliveredOutboundLine(a,outboundLine);
    var prior=db.queryForMap("SELECT coalesce(sum(l.qty),0) qty,coalesce(sum(l.amount),0) amount FROM rtn_sales_settlement_line l JOIN rtn_sales_settlement s ON s.country_id=l.country_id AND s.id=l.settlement_id WHERE l.country_id=? AND l.outbound_line_id=? AND s.status='EFFECTIVE'",a.requireCountry(),outboundLine);
    BigDecimal cumulativeQty=new BigDecimal(prior.get("qty").toString()).add(qty);
    if(cumulativeQty.compareTo(original.deliveredQty())>0)throw state("RTN_RETURN_EXCEEDED","累计结算数量超过原实际交付数量");
    // Parts retain actual outbound quantities. A REJECTED sign caps returnability,
    // while its accepted subset retains the same original price denominator.
    BigDecimal pricedQty=original.parts().stream().map(SalesSourceApi.DeliveryPart::qty).reduce(BigDecimal.ZERO,BigDecimal::add);
    if(pricedQty.signum()<=0||cumulativeQty.compareTo(pricedQty)>0)throw state("RTN_SOURCE_CONFLICT","原成交数量与实际出库不一致");
    BigDecimal target=cumulativeQty.compareTo(pricedQty)==0?money(original.originalAmount()):money(original.originalAmount().multiply(cumulativeQty).divide(pricedQty,12,RoundingMode.HALF_UP));
    amount=money(target.subtract(new BigDecimal(prior.get("amount").toString())));
    if(amount.signum()<0)throw state("RTN_AMOUNT_CONFLICT","原成交金额与历史退货结算不一致");
   }
   var allocation=new LinkedHashMap<String,Object>();allocation.put("line",l);allocation.put("qty",qty);allocation.put("amount",amount);allocations.add(allocation);total=total.add(amount);
  }
  var result=total.signum()==0?new ArReturnApi.Settlement(List.of(),null,BigDecimal.ZERO,BigDecimal.ZERO):Boolean.TRUE.equals(r.get("noOriginFlag"))?ar.settleNoOriginReturn(a,id(r,"bookId"),id,id(r,"customerId"),String.valueOf(r.get("currency")),total,date):ar.settleSalesReturn(a,id(r,"bookId"),id,id(r,"orderId"),id(r,"customerId"),String.valueOf(r.get("currency")),total,date);
  long settlement=db.queryForObject("INSERT INTO rtn_sales_settlement(country_id,return_id,book_id,biz_date,total_amount,ar_offset_amount,refundable_amount,credit_note_ids,writeoff_id) VALUES(?,?,?,?,?,?,?,?::jsonb,?) RETURNING id",Long.class,a.requireCountry(),id,r.get("bookId"),date,total,result.offsetAmount(),result.refundableAmount(),json.write(result.creditNoteIds()),result.writeoffId());
  for(var allocation:allocations){var l=map(allocation.get("line"));db.update("INSERT INTO rtn_sales_settlement_line(country_id,book_id,settlement_id,return_id,return_line_id,outbound_line_id,qty,amount) VALUES(?,?,?,?,?,?,?,?)",a.requireCountry(),r.get("bookId"),settlement,id,l.get("id"),l.get("outboundLineId"),allocation.get("qty"),allocation.get("amount"));}
  for(var l:lines)if(n(l,"reservedQty").signum()>0){if(l.get("orderLineId")!=null)sales.releaseReturn(a,id(l,"orderLineId"),n(l,"reservedQty"));db.update("UPDATE rtn_sales_return_line SET reserved_qty=0,version=version+1 WHERE country_id=? AND id=?",a.requireCountry(),l.get("id"));}
  db.update("UPDATE rtn_sales_return SET status='COMPLETED',settled_flag=true,short_reason=CASE WHEN ?='' THEN short_reason ELSE ? END,version=version+1 WHERE country_id=? AND id=?",Inputs.text(b,"shortReason",""),Inputs.text(b,"shortReason",""),a.requireCountry(),id);
  return finish(c,a,"RTN_SALES_SETTLED","sales",id,date,true);
 });}

