 public Map<String,Object> createClaim(RequestContext c,Map<String,Object>b,String key){return command(c,"rtn:claim:create","/api/v1/rtn/claims",b,key,"ORDER_TOTAL",a->{long book=resolver.resolve(a,b.get("bookId")==null?null:Inputs.id(b.get("bookId")),b.get("entityId")==null?null:Inputs.id(b.get("entityId")));long entity=id(row(a,"fin_book",book,false),"entityId");scopeBook(a,book,entity);LocalDate date=date(a,b,"bizDate");periods.assertOpen(a.requireCountry(),book,date);String type=Inputs.text(b,"claimType","CLAIM"),against=Inputs.text(b,"againstType","CARRIER");if(!Set.of("CLAIM","DAMAGE").contains(type)||!Set.of("SUPPLIER","CARRIER").contains(against))throw Inputs.bad("索赔类型不合法");long partner=Inputs.id(b.get("partnerId"));row(a,against.equals("SUPPLIER")?"md_supplier":"md_logistics_provider",partner,false);long id=db.queryForObject("INSERT INTO rtn_claim(country_id,entity_id,book_id,doc_no,claim_type,against_type,partner_id,discrepancy_id,batch_id,qty,claim_amount,currency,remark,biz_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,a.requireCountry(),entity,book,numbers.next(a,"RTN_CLAIM",date),type,against,partner,nullableId(b.get("discrepancyId")),nullableId(b.get("batchId")),b.get("qty")==null?BigDecimal.ZERO:nonnegative(b.get("qty")),positive(b.get("claimAmount")),Inputs.required(b,"currency"),Inputs.text(b,"remark",""),date);return finish(c,a,"RTN_CLAIM_CREATED","claims",id,date,false);});}
