 public List<Map<String,Object>> returnable(RequestContext c,long outbound){return tx.execute(s->{var a=auth.authorize(c);a.require("rtn:sales:create");var r=docs.requireDocumentAccess(a,"SALES_OUTBOUND",outbound,false);var lines=maps(r.get("lines"));var result=new ArrayList<Map<String,Object>>();for(var l:lines){var src=sales.lockDeliveredOutboundLine(a,id(l,"id"));BigDecimal occupied=db.queryForObject("SELECT coalesce(sum(l.inspected_qty+l.reserved_qty),0) FROM rtn_sales_return_line l JOIN rtn_sales_return r ON r.country_id=l.country_id AND r.id=l.return_id WHERE l.country_id=? AND l.outbound_line_id=? AND r.status NOT IN ('CANCELLED','REJECTED')",BigDecimal.class,a.requireCountry(),id(l,"id"));var line=new LinkedHashMap<String,Object>();line.put("outboundLineId",id(l,"id"));line.put("orderLineId",src.orderLineId());line.put("productId",src.productId());line.put("unitPrice",src.netUnitPrice());line.put("originPrice",src.netUnitPrice());line.put("returnableQty",src.deliveredQty().subtract(occupied).max(BigDecimal.ZERO));productName(a,line,src.productId());result.add(fields.mask(a,line,"ORDER_TOTAL"));}return result;});}
 public List<Map<String,Object>> purchaseReturnable(RequestContext c,long order,String stage){return tx.execute(s->{var a=auth.authorize(c);a.require("rtn:purchase:create","rtn:purchase:ship");if(!Set.of("DOMESTIC","MX_STOCK").contains(stage))throw Inputs.bad("请选择退供阶段");var sources=supply.listReturnSources(a,order,stage);var result=new ArrayList<Map<String,Object>>();if(sources.isEmpty())return result;long book=id(sources.getFirst(),"bookId");scopeBook(a,book,id(sources.getFirst(),"entityId"));if(stage.equals("DOMESTIC")){for(var source:sources){var r=new LinkedHashMap<>(source);BigDecimal pending=purchasePending(a,id(source,"poLineId"),stage,id(source,"sourceLineId"),null);BigDecimal all=purchasePending(a,id(source,"poLineId"),stage,null,null);r.put("returnableQty",n(source,"availableQty").subtract(pending).min(n(source,"orderAvailableQty").subtract(all)).max(BigDecimal.ZERO));productName(a,r,id(source,"productId"));result.add(fields.mask(a,r,"COST"));}}else{var ids=sources.stream().map(r->id(r,"poLineId")).toList();for(var batch:inventory.supplierReturnable(c,book,ids)){var src=sources.stream().filter(r->id(r,"poLineId")==batch.poLineId()).findFirst().orElseThrow();BigDecimal pending=purchasePending(a,batch.poLineId(),stage,null,batch.batchId()),all=purchasePending(a,batch.poLineId(),stage,null,null);var r=new LinkedHashMap<>(src);r.put("warehouseId",batch.warehouseId());r.put("batchId",batch.batchId());r.put("returnableQty",batch.availableQty().subtract(pending).min(n(src,"orderAvailableQty").subtract(all)).max(BigDecimal.ZERO));productName(a,r,batch.productId());result.add(fields.mask(a,r,"COST"));}}return result;});}
 private BigDecimal purchasePending(Access a,long line,String stage,Long source,Long batch){return db.queryForObject("SELECT coalesce(sum(l.qty),0) FROM rtn_purchase_return_line l JOIN rtn_purchase_return r ON r.country_id=l.country_id AND r.id=l.return_id WHERE l.country_id=? AND l.po_line_id=? AND r.stage=? AND r.status NOT IN ('COMPLETED','CANCELLED','REJECTED')"+(source==null&&batch==null?"":" AND coalesce(l.source_line_id,l.batch_id)=?"),BigDecimal.class,source==null&&batch==null?new Object[]{a.requireCountry(),line,stage}:new Object[]{a.requireCountry(),line,stage,source==null?batch:source});}
 private String name(Access a,String table,Object id){return db.queryForObject("SELECT name FROM "+table+" WHERE country_id=? AND id=?",String.class,a.requireCountry(),id);}
 private String docNo(Access a,String table,Object id){return db.queryForObject("SELECT doc_no FROM "+table+" WHERE country_id=? AND id=?",String.class,a.requireCountry(),id);}
 private void productName(Access a,Map<String,Object> row,long product){var reference=products.reference(a.requireCountry(),product);row.put("productCode",reference.code());row.put("productName",reference.name());}
 private void decision(RequestContext c,Access a,String kind,long id,String status){var r=row(a,table(kind),id,true);if(!Set.of("PENDING_APPROVAL","BLOCKED").contains(r.get("status")))return;
  String next="APPROVED".equals(status)?(kind.equals("sales")?"PENDING_RECEIPT":"APPROVED"):"REJECTED".equals(status)?"REJECTED":"CANCELLED";
  if(!"APPROVED".equals(status)&&kind.equals("sales")){for(var l:db.queryForList("SELECT * FROM rtn_sales_return_line WHERE country_id=? AND return_id=? ORDER BY order_line_id,id FOR UPDATE",a.requireCountry(),id).stream().map(DbRows::camel).toList()){if(n(l,"reservedQty").signum()>0&&l.get("orderLineId")!=null)sales.releaseReturn(a,ReturnsService.id(l,"orderLineId"),n(l,"reservedQty"));}db.update("UPDATE rtn_sales_return_line SET reserved_qty=0,version=version+1 WHERE country_id=? AND return_id=?",a.requireCountry(),id);}
  if(!"APPROVED".equals(status)&&kind.equals("refunds")){LocalDate date=db.queryForObject("SELECT (clock_timestamp() AT TIME ZONE timezone)::date FROM sys_country WHERE id=?",(rs,n)->rs.getDate(1).toLocalDate(),a.requireCountry());for(var l:db.queryForList("SELECT * FROM rtn_refund_source WHERE country_id=? AND refund_id=? AND status='RESERVED' ORDER BY credit_note_id FOR UPDATE",a.requireCountry(),id).stream().map(DbRows::camel).toList())ar.releaseRefund(a,ReturnsService.id(r,"bookId"),ReturnsService.id(r,"customerId"),String.valueOf(r.get("currency")),ReturnsService.id(l,"creditNoteId"),id,n(l,"amount"),date);db.update("UPDATE rtn_refund_source SET status='RELEASED',version=version+1 WHERE country_id=? AND refund_id=?",a.requireCountry(),id);}
  db.update("UPDATE "+table(kind)+" SET status=?,version=version+1 WHERE country_id=? AND id=?",next,a.requireCountry(),id);audit.append(c,"RTN_APPROVAL_"+status,type(kind),id,null,Map.of("status",next));
 }
 private Map<String,Object> command(RequestContext c,String permission,String endpoint,Map<String,Object>b,String key,String group,Function<Access,Map<String,Object>>work){return tx.execute(s->{var a=auth.authorize(c);a.require(permission);fields.requireWrite(a,b,group);return fields.mask(a,idem.execute(c,"POST",endpoint,key,b,b.get("bookId")==null?null:Inputs.id(b.get("bookId")),()->work.apply(a),a::requireRow),group);});}
 private Map<String,Object> locked(Access a,String kind,long id,Map<String,Object>b,boolean customer){var hint=row(a,table(kind),id,false);if(kind.equals("sales"))sourceBook(a,id(hint,"bookId"),id(hint,"returnWarehouseId"));else scopeBook(a,id(hint,"bookId"),id(hint,"entityId"));if(customer)ar.lockCustomer(a,id(hint,"bookId"),id(hint,"customerId"),String.valueOf(hint.get("currency")));var r=docs.requireLockedDocumentAccess(a,type(kind),id,true);if(b.containsKey("version")&&((Number)r.get("version")).longValue()!=Inputs.version(b))throw Inputs.conflict();return r;}
 private void sourceBook(Access a,long book,long warehouse){resolver.resolveForWarehouse(a,book,warehouse);gates.lock(a.requireCountry(),book,false);}
 private void scopeBook(Access a,long book,long entity){resolver.resolve(a,book,entity);gates.lock(a.requireCountry(),book,false);}
 private void warehouse(Access a,long warehouse,long entity){var r=row(a,"org_warehouse",warehouse,false);if(id(r,"entityId")!=entity||!"ENABLED".equals(r.get("status")))throw Inputs.bad("退回仓须是本主体启用仓库");}
 private Map<String,Object> line(Access a,String table,long returnId,long id){var r=row(a,table,id,true);if(id(r,"returnId")!=returnId)throw ApiException.notFound();return r;}
 private Map<String,Object> finish(RequestContext c,Access a,String event,String kind,long id,LocalDate date,boolean publish){var r=detail(a,kind,row(a,table(kind),id,false));audit.append(c,event,type(kind),id,null,r);if(publish){int seq=db.queryForObject("SELECT coalesce(max(event_seq),0)+1 FROM sys_biz_event WHERE country_id=? AND event_type=? AND source_type=? AND source_id=?",Integer.class,a.requireCountry(),event,type(kind),id);events.publish(a.requireCountry(),id(r,"bookId"),event,type(kind),id,seq,date,r);}return r;}
 private AttachmentService.PreparedEvidence prepare(RequestContext c,Map<String,Object>b,long id){return attachments.prepareEvidence(c,"REFUND",id,"REFUND_PROOF",b.get("proof")==null?Map.of():map(b.get("proof")));}
 private static String table(String kind){return switch(kind){case "sales"->"rtn_sales_return";case "refunds"->"rtn_refund";case "purchase"->"rtn_purchase_return";case "claims"->"rtn_claim";default->throw ApiException.notFound();};}
 private static String type(String kind){return switch(kind){case "sales"->"SALES_RETURN";case "refunds"->"REFUND";case "purchase"->"PURCHASE_RETURN";case "claims"->"CLAIM";default->throw ApiException.notFound();};}
 private static String permission(String kind){return switch(kind){case "sales"->"rtn:sales:create";case "refunds"->"rtn:refund:create";case "purchase"->"rtn:purchase:create";case "claims"->"rtn:claim:create";default->throw ApiException.notFound();};}
 private static long id(Map<String,Object>b,String key){return Inputs.id(b.get(key));}private static Long nullableId(Object v){return v==null?null:Inputs.id(v);}
 private static BigDecimal n(Map<String,Object>b,String key){return b.get(key)==null?BigDecimal.ZERO:new BigDecimal(b.get(key).toString());}
 private static BigDecimal nonnegative(Object v){var n=Inputs.decimal(v,4,Inputs.PUBLIC_DECIMAL_MAX);if(n.signum()<0)throw Inputs.bad("数量金额不能为负");return n;}
 private static BigDecimal positive(Object v){var n=nonnegative(v);if(n.signum()==0)throw Inputs.bad("数量金额须大于零");return n;}
 private static BigDecimal money(BigDecimal v){return Inputs.decimal(v.setScale(4,RoundingMode.HALF_UP),4,Inputs.PUBLIC_DECIMAL_MAX);}
 private LocalDate date(Access a,Map<String,Object>b,String key){if(b.get(key)==null)return calendar.today(a);try{String value=Inputs.required(b,key);return value.length()==10?LocalDate.parse(value):calendar.day(a,java.time.OffsetDateTime.parse(value));}catch(java.time.DateTimeException|IndexOutOfBoundsException e){throw Inputs.bad("请填写有效"+key);}}

 private static ApiException state(String code,String message){return new ApiException(409,code,message);}
 private static Map<String,Object>map(Object v){if(!(v instanceof Map<?,?>m))throw Inputs.bad("请求对象不合法");var r=new LinkedHashMap<String,Object>();m.forEach((k,x)->r.put(String.valueOf(k),x));return r;}
 private static List<Map<String,Object>>maps(Object v){if(!(v instanceof List<?>list))throw Inputs.bad("请填写业务行");return new ArrayList<>(list.stream().map(ReturnsService::map).toList());}
 private static Map<String,Object>page(List<Map<String,Object>>r,Map<String,String>q){int p=Integer.parseInt(q.getOrDefault("page","1")),size=Integer.parseInt(q.getOrDefault("size","20"));if(p<1||size<1||size>200)throw Inputs.bad("分页参数不合法");int start=Math.min(r.size(),(p-1)*size);return Map.of("records",r.subList(start,Math.min(r.size(),start+size)),"total",r.size(),"page",p,"size",size);}
